def add_repr(*fields):
    def decorate(cls):
        def __repr__(self):
            body = ", ".join(f"{name}={getattr(self, name)!r}" for name in fields)
            return f"{type(self).__name__}({body})"

        cls.__repr__ = __repr__
        return cls

    return decorate

