class Temperature:
    def __init__(self, celsius):
        self.celsius = float(celsius)

    def __format__(self, spec):
        if spec == "":
            spec = "c"
        unit = spec[-1]
        number_spec = spec[:-1] or ".1"
        if unit == "c":
            value, suffix = self.celsius, "C"
        elif unit == "f":
            value, suffix = self.celsius * 9 / 5 + 32, "F"
        else:
